window.VeilGardeData.files["Tests-VeilGardeCoreTests"] = {"group":"Tests-VeilGardeCoreTests","files":[{"path":"Tests/VeilGardeCoreTests/BoostTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,80]],"header":{"lines":[1,9],"target":"VeilGardeCoreTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1753,"scopes":[["S","BoostTests",null,"",15,16,[16,18],80,null,-1,0,"a"],["f","byteIdentity",["name"],"",17,18,[18,43],23,null,0,0,"a"],["f","warpShape",[],"",25,26,[26,28],32,null,0,0,"a"],["f","matchesXGBoost",[],"",34,35,[35,33],46,null,0,0,"a"],["f","fusionLineage",[],"",48,49,[49,32],59,null,0,0,"a"],["f","freshModel",[],"",61,62,[62,29],79,null,0,0,"a"]],"old":"","new":"//\n//  BoostTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: GBDTModel against the shipped boosters: decoding then encoding writes each file's exact\n//        bytes; predictions match xgboost 3.2's on seeded rows; the fusion head is its frozen\n//        reference plus warm-start trees; a fresh model encodes and decodes to itself.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Boost codec and evaluator\")\nstruct BoostTests {\n    @Test(\"each shipped booster round-trips to its exact bytes\", arguments: [\"warp_tile32.xgb.json\", \"fusion_head.xgb.json\", \"fusion_ref.xgb.json\"])\n    func byteIdentity(name: String) throws {\n        let data = try Data(contentsOf: Fixture.resource(name))\n        let model = try GBDTModel.decode(xgboostJSON: data)\n        let encoded = model.encodeXGBoostJSON()\n        #expect(encoded == data, \"\\(name): \\(encoded.count) bytes vs \\(data.count)\")\n    }\n\n    @Test(\"the warp tile model is 200 trees of depth 8 over 19 features\")\n    func warpShape() throws {\n        let model = try GBDTModel.load(Fixture.resource(\"warp_tile32.xgb.json\"))\n        #expect(model.trees.count == 200)\n        #expect(model.featureCount == 19)\n        #expect(model.trees.map(\\.depth).max() == 8)\n        #expect(model.baseScore == \"[5.11784E-1]\")\n    }\n\n    @Test(\"predictions match xgboost 3.2 on the warp and fusion boosters\")\n    func matchesXGBoost() throws {\n        let reference = try Fixture.json(\"boost_reference.json\")\n        for (key, file) in [(\"warp\", \"warp_tile32.xgb.json\"), (\"fusion\", \"fusion_head.xgb.json\")] {\n            let model = try GBDTModel.load(Fixture.resource(file))\n            let block = reference[key] as! [String: Any]\n            let rows = (block[\"rows\"] as! [[NSNumber]]).map { $0.map(\\.floatValue) }\n            let expected = floats(block[\"p\"])\n            let got = model.scoreBatch(rows)\n            let worst = zip(got, expected).map { abs($0 - $1) }.max() ?? 0\n            #expect(worst < 2e-6, \"\\(key): max |Δp| \\(worst)\")\n        }\n    }\n\n    @Test(\"the fusion head is the frozen reference plus 40 warm-start trees\")\n    func fusionLineage() throws {\n        let head = try GBDTModel.load(Fixture.resource(\"fusion_head.xgb.json\"))\n        let reference = try GBDTModel.load(Fixture.resource(\"fusion_ref.xgb.json\"))\n        #expect(head.trees.count == 940)\n        #expect(reference.trees.count == 900)\n        #expect(head.featureCount == 397)\n        let shared = zip(head.trees.prefix(900), reference.trees).allSatisfy { a, b in\n            a.leftChildren == b.leftChildren && a.splitIndices == b.splitIndices && a.splitConditions == b.splitConditions && a.baseWeights == b.baseWeights\n        }\n        #expect(shared)\n    }\n\n    @Test(\"a fresh model encodes, decodes and predicts as built\")\n    func freshModel() throws {\n        // root: x0 < 0.5 → leaf −0.2, else x1 < 1 → leaf 0.1 | leaf 0.3\n        let tree = GBDTModel.Tree(id: 0, leftChildren: [1, -1, 3, -1, -1], rightChildren: [2, -1, 4, -1, -1],\n                                  parents: [GBDTModel.Tree.rootParent, 0, 0, 2, 2], splitIndices: [0, 0, 1, 0, 0],\n                                  splitConditions: [0.5, -0.2, 1, 0.1, 0.3], baseWeights: [0.01, -0.2, 0.05, 0.1, 0.3],\n                                  defaultLeft: [0, 0, 0, 0, 0], splitType: [0, 0, 0, 0, 0], lossChanges: [3, 0, 1.5, 0, 0],\n                                  sumHessian: [10, 4, 6, 3, 3], numFeature: 2)\n        let model = GBDTModel(trees: [tree], baseScoreProbability: 0.25, featureCount: 2)\n        let decoded = try GBDTModel.decode(xgboostJSON: model.encodeXGBoostJSON())\n        #expect(decoded.trees.count == 1)\n        #expect(decoded.trees[0].splitConditions == tree.splitConditions)\n        #expect(decoded.featureCount == 2)\n        #expect(decoded.encodeXGBoostJSON() == model.encodeXGBoostJSON())\n        let logit = Float(log(0.25 / 0.75))\n        #expect(abs(decoded.margin([0.2, 0]) - (logit - 0.2)) < 1e-6)\n        #expect(abs(decoded.margin([0.9, 2]) - (logit + 0.3)) < 1e-6)\n        #expect(decoded.margin([0.9]) == decoded.margin([0.9, 0]))   // a missing column reads 0\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/BundleTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,48]],"header":{"lines":[1,8],"target":"VeilGardeCoreTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1759,"scopes":[["S","BundleTests",null,"",14,15,[15,19],48,null,-1,0,"a"],["f","shippedBundleVerifies",[],"",16,17,[17,40],27,null,0,0,"a"],["f","tamperRefused",[],"",29,30,[30,32],40,null,0,0,"a"],["f","frozenRoles",[],"",42,43,[43,23],47,null,0,0,"a"]],"old":"","new":"//\n//  BundleTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The shipped bundle is exactly the bytes its manifest names; a moved file is refused; the\n//        frozen roles are the ones the flywheel may never promote over.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Bundle manifest\")\nstruct BundleTests {\n    @Test(\"the shipped bundle's manifest verifies every artifact\")\n    func shippedBundleVerifies() throws {\n        let bundle = try ModelBundle.load(Fixture.resources)\n        #expect(bundle.manifest.artifacts.count == 14)\n        #expect(bundle.manifest.weights.count == 4)\n        #expect(bundle.sha256(.warpTile) == \"516119c92d364dda3dba41dcfc42e06edf0f42e45efd3b54c44ab620f7eefe3d\")\n        #expect(bundle.sha256(.warpTile) == bundle.sha256(.warpMajoritySensor))\n        #expect(bundle.manifest.artifact(.fusionHead)?.parent == bundle.sha256(.fusionReference))\n        for head in HeadKind.allCases where head != .artPair { #expect(bundle.url(.head, head: head) != nil, \"no \\(head.rawValue) head\") }\n        #expect(bundle.url(.head, head: .artPair) == nil, \"the art-pair head left the bundle with its adjudicator\")\n        #expect(bundle.manifest.history.map(\\.slot).suffix(2) == [\"calibration\", \"combiner\"], \"the two cuts and the combiner without the art-pair, recorded\")\n    }\n\n    @Test(\"a file that moved under its manifest is refused\")\n    func tamperRefused() throws {\n        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-bundle-\\(UUID().uuidString)\")\n        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)\n        defer { try? FileManager.default.removeItem(at: dir) }\n        try Data(\"{}\".utf8).write(to: dir.appendingPathComponent(\"a.json\"))\n        let manifest = BundleManifest(artifacts: [try ModelBundle.record(.combiner, file: \"a.json\", in: dir)])\n        try JSONCoding.write(manifest, to: dir.appendingPathComponent(BundleManifest.fileName))\n        _ = try ModelBundle.load(dir)\n        try Data(\"{ }\".utf8).write(to: dir.appendingPathComponent(\"a.json\"))\n        #expect(throws: VeilGardeFailure.self) { try ModelBundle.load(dir) }\n    }\n\n    @Test(\"frozen roles are the warp models, the fusion reference, noiseprint and the backbones\")\n    func frozenRoles() {\n        let frozen = Set(ArtifactRole.allCases.filter(\\.isFrozen))\n        #expect(frozen == [.warpTile, .warpMajoritySensor, .fusionReference, .noiseprint, .dinov2Small, .dinov2XSmall, .dinov2XXSmall, .clipVision])\n        #expect(!ArtifactRole.fusionHead.isFrozen && !ArtifactRole.head.isFrozen && !ArtifactRole.combiner.isFrozen)\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/Fixture.swift","status":"added","lang":"swift","hunks":[[1,0,1,37]],"header":{"lines":[1,8],"target":"VeilGardeCoreTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1763,"scopes":[["E","Fixture",null,"",13,13,[13,13],34,null,-1,0,"a",[]],["f","resource",["_"],"static",22,22,[22,48],22,null,0,8,"a"],["f","url",["_"],"static",24,24,[24,43],24,null,0,8,"a"],["f","json",["_"],"static",26,26,[26,61],28,null,0,0,"a"],["f","floats",["_"],"",36,36,[36,36],36,null,-1,8,"a"],["f","float",["_"],"",37,37,[37,34],37,null,-1,8,"a"]],"old":"","new":"//\n//  Fixture.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Paths the Core tests read: their committed fixtures (written once from the Python\n//        reference) and the shipped bundle's resources, both by repo path.\n//\n\nimport Foundation\nimport VeilGardeCore\n\nenum Fixture {\n    static let repoRoot: URL = {\n        var url = URL(fileURLWithPath: #filePath)\n        while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n        return url.deletingLastPathComponent()\n    }()\n\n    static let resources = repoRoot.appendingPathComponent(\"Sources/VeilGardeInference/Resources\")\n\n    static func resource(_ name: String) -> URL { resources.appendingPathComponent(name) }\n\n    static func url(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeCoreTests/Fixtures/\\(name)\") }\n\n    static func json(_ name: String) throws -> [String: Any] {\n        try JSONSerialization.jsonObject(with: Data(contentsOf: url(name))) as! [String: Any]\n    }\n\n    /// The work area's feature store, when this Mac has it (the Store suite reads one small shard\n    /// from it); VEILGARDE_SEED_STORE names another.\n    static let seedStore = URL(fileURLWithPath: ProcessInfo.processInfo.environment[\"VEILGARDE_SEED_STORE\"]\n        ?? WorkArea.resolve()?.shards.path ?? \"store/shards\")\n}\n\nfunc floats(_ any: Any?) -> [Float] { (any as? [NSNumber])?.map { $0.floatValue } ?? [] }\nfunc float(_ any: Any?) -> Float? { (any as? NSNumber)?.floatValue }\n"},{"path":"Tests/VeilGardeCoreTests/GridTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,80]],"header":{"lines":[1,8],"target":"VeilGardeCoreTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1769,"scopes":[["S","GridTests",null,"",14,15,[15,17],80,null,-1,0,"a"],["f","weightMap",[],"",16,17,[17,28],33,null,0,0,"a"],["f","hotspotOff",[],"",35,36,[36,22],43,null,0,0,"a"],["f","labels",[],"",45,46,[46,18],53,null,0,0,"a"],["f","tileGrid",[],"",55,56,[56,20],62,null,0,0,"a"],["f","featureOrders",[],"",64,65,[65,32],79,null,0,0,"a"]],"old":"","new":"//\n//  GridTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The weight map, the weighted verdict and sharpness against float32 replicas of Garde's\n//        loops (written once from the Python reference); the three-state label's open band; the grid.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Grid and verdict\")\nstruct GridTests {\n    @Test(\"weight map, weighted score and sharpness match the float32 replica\")\n    func weightMap() throws {\n        let reference = try Fixture.json(\"weightmap_reference.json\")\n        for case let c as [String: Any] in reference[\"cases\"] as! [Any] {\n            let patch = (c[\"patch\"] as! [[NSNumber]]).map { $0.map(\\.floatValue) }\n            let tex = (c[\"tex\"] as! [[NSNumber]]).map { $0.map(\\.floatValue) }\n            let expected = (c[\"weights\"] as! [[NSNumber]]).map { $0.map(\\.floatValue) }\n            let weights = WeightMap.build(patchGrid: patch, texWeights: tex, parameters: WeightMapParameters())\n            let worst = zip(weights.flatMap { $0 }, expected.flatMap { $0 }).map { abs($0 - $1) }.max() ?? 0\n            #expect(worst < 1e-6, \"\\(patch.count)×\\(patch[0].count): max |Δw| \\(worst)\")\n            let score = WeightedVerdict.score(patchGrid: patch, weightMap: weights, hotspot: HotspotRule())\n            #expect(abs(score - float(c[\"score\"])!) < 1e-6)\n            let sharp = SharpnessFeatures.measure(texWeights: tex, weightMap: weights)\n            #expect(abs(sharp.salientSharp - float(c[\"salient\"])!) < 1e-4)\n            #expect(abs(sharp.globalSharp - float(c[\"global\"])!) < 1e-4)\n            #expect(abs(sharp.sharpRatio - float(c[\"ratio\"])!) < 1e-5)\n        }\n    }\n\n    @Test(\"hotspot off is the plain weighted mean\")\n    func hotspotOff() {\n        let p: [[Float]] = [[0.9, 0.1]], w: [[Float]] = [[0.5, 0.5]]\n        #expect(WeightedVerdict.score(patchGrid: p, weightMap: w, hotspot: HotspotRule(mode: .off)) == 0.5)\n        // Symmetric: both patches are confident, mean 0.5, so the blend keeps 0.5.\n        #expect(abs(WeightedVerdict.score(patchGrid: p, weightMap: w, hotspot: HotspotRule()) - 0.5) < 1e-7)\n        // Asymmetric: only 0.9 pulls, up.\n        #expect(WeightedVerdict.score(patchGrid: p, weightMap: w, hotspot: HotspotRule(mode: .asymmetric)) > 0.5)\n    }\n\n    @Test(\"the band is open and generated is strictly above the threshold\")\n    func labels() {\n        let rule = DecisionRule.warpWeighted\n        #expect(rule.label(0.56) == \"inconclusive\")\n        #expect(rule.label(0.60) == \"generated\")   // exactly the band edge is decisive\n        #expect(rule.label(0.52) == \"real\")\n        #expect(rule.label(0.61) == \"generated\")\n        #expect(DecisionRule.fusion.label(0.53) == \"inconclusive\")\n    }\n\n    @Test(\"a tile grid indexes row-major and returns its rows\")\n    func tileGrid() {\n        var grid = TileGrid(rows: 2, cols: 3, values: [1, 2, 3, 4, 5, 6] as [Float])\n        #expect(grid[1, 0] == 4)\n        grid[0, 2] = 9\n        #expect(grid.rowsArray == [[1, 2, 9], [4, 5, 6]])\n        #expect(TileGrid([[1, 2], [3, 4]] as [[Float]]).values == [1, 2, 3, 4])\n    }\n\n    @Test(\"the feature vectors keep their trained column orders\")\n    func featureOrders() throws {\n        let row = (0..<19).map(Float.init)\n        let features = try WarpFeatures(vector: row)\n        #expect(features.asVector == row)\n        #expect(features.fr == 0 && features.nyqR == 18 && features.cfaG == 11 && features.noiseRatio == 16)\n        #expect(WarpFeatures.names.count == 19 && WarpFeatures.name(ofColumn: 18) == \"nyq_R\")\n        let capture = CaptureFeatures(vector: [42, 1, 1, 1024, 3, 0.4, 0.5, 0.1, 0.2])\n        #expect(capture.signature == CaptureSignature(peak: 42, valid: true, nativePixels: 1024, present: true))\n        let vector = FusionVector(warp: 0.7, dino: [Float](repeating: 0.5, count: 384), capture: capture,\n                                  sharpness: SharpnessFeatures(salientSharp: 10, globalSharp: 5, sharpRatio: 2))\n        let flat = vector.asVector\n        #expect(flat.count == 397 && FusionVector.count == 397)\n        #expect(flat[0] == 0.7 && flat[385] == 42 && flat[388] == 1024 && flat[394] == 10 && flat[396] == 2)\n        #expect(FusionVector.names.count == 397)\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/HeadsTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,86]],"header":{"lines":[1,9],"target":"VeilGardeCoreTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1775,"scopes":[["S","HeadsTests",null,"",15,16,[16,18],86,null,-1,0,"a"],["f","linearHead",[],"",17,18,[18,29],27,null,0,0,"a"],["f","shippedHeads",["file"],"",33,33,[33,43],36,null,0,0,"a"],["f","headFile",[],"",38,39,[39,27],46,null,0,0,"a"],["f","combinerWeights",[],"",48,49,[49,34],63,null,0,0,"a"],["f","combinerArithmetic",[],"",65,66,[66,37],78,null,0,0,"a"],["f","combinerFile",[],"",80,81,[81,31],85,null,0,0,"a"]],"old":"","new":"//\n//  HeadsTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The linear head and the stack combiner against float32 replicas of Garde's arithmetic\n//        (written once from the Python reference), the shipped combiner as Garde's weights without the\n//        art-pair adjudicator, and the trainer's file forms loading back as the runtime types.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Heads and combiner\")\nstruct HeadsTests {\n    @Test(\"the art head's P(AI) matches the float32 replica\")\n    func linearHead() throws {\n        let reference = try Fixture.json(\"head_reference.json\")\n        let head = try LinearHead.load(Fixture.resource(\"art_dinov2_v2.json\"))\n        #expect(head.coef.count == 384)\n        #expect(head.normW == 360 && head.normH == 640)\n        for case let c as [String: Any] in reference[\"cases\"] as! [Any] {\n            let p = head.pAI(floats(c[\"embedding\"]))\n            #expect(abs(p - float(c[\"p\"])!) < 1e-6)\n        }\n    }\n\n    @Test(\"every shipped head decodes with 384 coefficients\", arguments: [\n        \"screenshot_dinov2_v1.10.json\", \"art_dinov2_v2.json\", \"blur_dinov2_v1.json\", \"human_dinov2_v4.json\",\n        \"semtile_dinov2_v1.json\", \"cgi_dinov2_v1.json\", \"preview_dinov2_v1.json\",\n    ])\n    func shippedHeads(file: String) throws {\n        let head = try LinearHead.load(Fixture.resource(file))\n        #expect(head.coef.count == 384 && head.mean.count == 384 && head.scale.count == 384)\n    }\n\n    @Test(\"a HeadFile written by the trainer loads as the head it describes\")\n    func headFile() throws {\n        let file = HeadFile(model: \"test_dinov2\", scalerMean: [0, 1], scalerScale: [1, 2], coef: [0.5, -0.25], intercept: 0.1)\n        let head = try file.linearHead()\n        let z: Float = 0.1 + 0.5 * 1 + ((3 - 1) / 2) * -0.25\n        #expect(abs(head.pAI([1, 3]) - 1 / (1 + exp(-z))) < 1e-7)\n        let text = String(decoding: try JSONCoding.prettyEncoder().encode(file), as: UTF8.self)\n        #expect(text.contains(\"\\\"scaler_mean\\\"\") && text.contains(\"\\\"fire_threshold\\\"\") && text.contains(\"\\\"embed_source\\\"\"))\n    }\n\n    @Test(\"the shipped combiner is Garde's weights without the art-pair adjudicator\")\n    func combinerWeights() throws {\n        let c = try StackCombiner.load(Fixture.resource(\"stack_combiner_v2.json\"))\n        #expect(abs(c.w0 - -0.6754975) < 1e-6)\n        #expect(abs(c.wBase - 3.8205218) < 1e-6)\n        #expect(c.wGen.count == 3 && c.wGen[0] == 0 && c.wGen[1] == 0 && abs(c.wGen[2] - 0.19669296) < 1e-6)\n        #expect(c.wRescue == 0.5 && c.wNp == 0.8 && c.capBase == 4 && c.capHead == 2 && c.gateCeiling == 0.75 && c.pairAdjudicates == false)\n        // Garde's v1, the same weights adjudicated by the art-pair: an art-pair under the art head pulls the pool down; v2 ignores it.\n        var v1 = try StackCombiner.load(Fixture.url(\"stack_combiner_v1.json\"))\n        #expect(v1.pairAdjudicates == true)\n        let heads: [Float] = [0.9, 0.2, 0.1]\n        #expect(v1.pool(base: 0.6, heads: heads, pairAI: 0.05) < v1.pool(base: 0.6, heads: heads))\n        #expect(c.pool(base: 0.6, heads: heads, pairAI: 0.05) == c.pool(base: 0.6, heads: heads))\n        v1.pairAdjudicates = false\n        #expect(v1 == c)\n    }\n\n    @Test(\"pool and contribution match the float32 replica on 43 tuples\")\n    func combinerArithmetic() throws {\n        let reference = try Fixture.json(\"combiner_reference.json\")\n        let c = try StackCombiner.load(Fixture.url(\"stack_combiner_v1.json\"))\n        for case let t as [String: Any] in reference[\"cases\"] as! [Any] {\n            let base = float(t[\"base\"])!, heads = floats(t[\"heads\"])\n            let pair = float(t[\"pair\"]), np = float(t[\"np\"])\n            #expect(abs(c.pool(base: base, heads: heads, pairAI: pair, np: np) - float(t[\"pool\"])!) < 1e-6)\n            let expected = floats(t[\"contribution\"])\n            for k in 0..<3 { #expect(abs(c.contribution(k, base: base, heads: heads, pairAI: pair) - expected[k]) < 1e-6) }\n        }\n        // Neutral heads at an even base: only w0 speaks.\n        #expect(abs(c.pool(base: 0.5, heads: [0.5, 0.5, 0.5]) - 1 / (1 + exp(0.6754975))) < 1e-6)\n    }\n\n    @Test(\"a CombinerFile loads as the combiner it describes\")\n    func combinerFile() throws {\n        let file = CombinerFile(w0: -0.5, wBase: 3, wGen: [0, 0.1, 0.2], wRescue: 0.5, wNp: 0.8, note: \"test\")\n        let c = try file.combiner()\n        #expect(c.wGen == [0, 0.1, 0.2] && c.wNp == 0.8 && c.pairAdjudicates == true && c.gateCeiling == 0.75)\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/PackageLayeringTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,275]],"header":{"lines":[1,13],"target":"VeilGardeCoreTests","what":[6,12],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1782,"scopes":[["f","text",["_"],"private",27,27,[27,55],29,null,-1,0,"a"],["f","swiftFiles",["under"],"private",31,31,[31,57],37,null,-1,0,"a"],["S","ManifestTarget",null,"private",40,40,[40,30],45,[39,39],-1,0,"a"],["f","manifestTargets",[],"private",47,47,[47,58],79,null,-1,0,"a"],["f","module",["ofProduct"],"private",82,82,[82,57],82,[81,81],-1,8,"a"],["f","imports",["in"],"private",95,95,[95,50],103,null,-1,0,"a"],["S","PackageLayeringTests",null,"",105,106,[106,28],275,null,-1,0,"a"],["f","products",[],"",119,120,[120,27],128,null,6,0,"a"],["f","layerTable",[],"",130,131,[131,29],137,null,6,0,"a"],["f","mlxThroughFrigate",[],"",139,140,[140,36],150,null,6,0,"a"],["f","importsAreDeclared",[],"",152,153,[153,37],186,null,6,0,"a"],["f","closure",["_"],"",156,156,[156,52],166,null,10,4,"a"],["f","noForbiddenImports",[],"",188,189,[189,37],200,null,6,0,"a"],["f","noFrigateReimplementation",[],"",202,203,[203,44],219,null,6,0,"a"],["f","names",[],"",221,222,[222,24],233,null,6,0,"a"],["f","bundleModuleInOneFile",[],"",235,236,[236,40],243,null,6,0,"a"],["f","headers",[],"",245,246,[246,26],256,null,6,0,"a"],["f","licenses",[],"",258,259,[259,27],274,null,6,0,"a"]],"old":"","new":"//\n//  PackageLayeringTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The manifest and the sources to the package's rules, as text over Package.swift,\n//        Sources/, Tests/ and Playground/: exactly four products; the layer table (which target\n//        may depend on which); MLX only through Frigate, each Frigate module imported only by a\n//        target that lists its product; Core on Foundation and Crypto alone; nothing imports\n//        MLXLLM, MLXLMCommon, AppKit or UIKit; nothing re-declares a Frigate function; no type is\n//        named like a module; Bundle.module in one file; every Swift file opens with its name, its\n//        target, its license and its WHAT; every script, manifest and site script names GPL-3.0.\n//\n\nimport Foundation\nimport Testing\n\nprivate let repoRoot: URL = {\n    var url = URL(fileURLWithPath: #filePath)\n    while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n    return url.deletingLastPathComponent()\n}()\n\n/// The identifier every source file carries (LICENSE holds the text).\nprivate let license = \"SPDX-License-Identifier: GPL-3.0-only\"\n\nprivate func text(_ relative: String) throws -> String {\n    try String(contentsOf: repoRoot.appendingPathComponent(relative), encoding: .utf8)\n}\n\nprivate func swiftFiles(under relative: String) -> [URL] {\n    let root = repoRoot.appendingPathComponent(relative)\n    guard let walker = FileManager.default.enumerator(at: root, includingPropertiesForKeys: nil) else { return [] }\n    return walker.compactMap { $0 as? URL }\n        .filter { $0.pathExtension == \"swift\" && !$0.path.contains(\"/.build/\") && !$0.path.contains(\"/.work/\") && !$0.lastPathComponent.hasPrefix(\"._\") }\n        .sorted { $0.path < $1.path }\n}\n\n/// One `.target(`, `.executableTarget(` or `.testTarget(` block of the manifest, read as text.\nprivate struct ManifestTarget {\n    var name: String\n    var kind: String\n    var targets: Set<String>\n    var products: Set<String>\n}\n\nprivate func manifestTargets() throws -> [ManifestTarget] {\n    let manifest = try text(\"Package.swift\")\n    let opener = try NSRegularExpression(pattern: #\"\\.(target|executableTarget|testTarget)\\(\\s*name:\\s*\"(\\w+)\"\"#)\n    let product = try NSRegularExpression(pattern: #\"\\.product\\(name:\\s*\"(\\w+)\",\\s*package:\\s*\"([\\w-]+)\"\\)\"#)\n    let quoted = try NSRegularExpression(pattern: #\"\"(\\w+)\"\"#)\n    let ns = manifest as NSString\n    let matches = opener.matches(in: manifest, range: NSRange(location: 0, length: ns.length))\n    var result: [ManifestTarget] = []\n    for (i, match) in matches.enumerated() {\n        let end = i + 1 < matches.count ? matches[i + 1].range.location : ns.length\n        let block = ns.substring(with: NSRange(location: match.range.location, length: end - match.range.location))\n        let kind = ns.substring(with: match.range(at: 1))\n        let name = ns.substring(with: match.range(at: 2))\n        var dependencies = \"\"\n        if let start = block.range(of: \"dependencies:\") {\n            let rest = block[start.upperBound...]\n            if let close = rest.firstIndex(of: \"]\") { dependencies = String(rest[..<close]) }\n        }\n        let depNS = dependencies as NSString\n        var products: Set<String> = []\n        for found in product.matches(in: dependencies, range: NSRange(location: 0, length: depNS.length)) {\n            products.insert(depNS.substring(with: found.range(at: 1)))\n        }\n        let stripped = product.stringByReplacingMatches(in: dependencies, range: NSRange(location: 0, length: depNS.length), withTemplate: \"\")\n        let strippedNS = stripped as NSString\n        var targets: Set<String> = []\n        for found in quoted.matches(in: stripped, range: NSRange(location: 0, length: strippedNS.length)) {\n            targets.insert(strippedNS.substring(with: found.range(at: 1)))\n        }\n        result.append(ManifestTarget(name: name, kind: kind, targets: targets, products: products))\n    }\n    return result\n}\n\n/// The module a Frigate product builds (they share a name except the hub).\nprivate func module(ofProduct product: String) -> String { product == \"FrigateHub\" ? \"Hub\" : product }\n\nprivate let frigateModules: Set<String> = [\n    \"Frigate\", \"MLX\", \"MLXNN\", \"MLXFFT\", \"MLXAccelerate\", \"MLXOptimizers\", \"MLXRandom\", \"MLXLinalg\", \"MLXFast\",\n    \"Hub\", \"Tokenizers\", \"MLXLLM\", \"MLXVLM\", \"MLXLMCommon\", \"MLXEmbedders\", \"FrigateBridge\", \"FrigateParallel\",\n]\n\nprivate let systemModules: Set<String> = [\n    \"Foundation\", \"Dispatch\", \"Darwin\", \"CoreGraphics\", \"ImageIO\", \"UniformTypeIdentifiers\", \"CoreFoundation\", \"os\", \"AppKit\",\n    // Apple's Accelerate (CPU BLAS for the linear solvers), not Frigate's MLX-backed MLXAccelerate.\n    \"Accelerate\",\n]\n\nprivate func imports(in body: String) -> [String] {\n    body.split(separator: \"\\n\").compactMap { line in\n        let trimmed = line.trimmingCharacters(in: .whitespaces)\n        for prefix in [\"@_exported import \", \"@testable import \", \"import \"] where trimmed.hasPrefix(prefix) {\n            return String(trimmed.dropFirst(prefix.count).split(separator: \" \").first ?? \"\")\n        }\n        return nil\n    }\n}\n\n@Suite(\"Package layering\")\nstruct PackageLayeringTests {\n    /// Who may depend on whom. A new edge is a design change: change this table on purpose.\n    static let layers: [String: Set<String>] = [\n        \"VeilGardeCore\": [],\n        \"VeilGardeLens\": [\"VeilGardeCore\"],\n        \"VeilGardeInference\": [\"VeilGardeLens\"],\n        \"VeilGardeTraining\": [\"VeilGardeLens\"],\n        \"VeilGardeFlywheel\": [\"VeilGardeTraining\", \"VeilGardeInference\"],\n        \"VeilWatermark\": [\"VeilGardeLens\"],\n        \"VeilGarde\": [\"VeilGardeInference\", \"VeilGardeTraining\", \"VeilGardeFlywheel\", \"VeilWatermark\"],\n        \"VeilGardeCLI\": [\"VeilGarde\"],\n    ]\n\n    @Test(\"four products: VeilGarde, VeilGardeInference, VeilWatermark and the veilgarde executable\")\n    func products() throws {\n        let manifest = try text(\"Package.swift\")\n        #expect(manifest.contains(\".library(name: \\\"VeilGarde\\\"\"))\n        #expect(manifest.contains(\".library(name: \\\"VeilGardeInference\\\"\"))\n        #expect(manifest.contains(\".library(name: \\\"VeilWatermark\\\"\"))\n        #expect(manifest.contains(\".executable(name: \\\"veilgarde\\\"\"))\n        #expect(manifest.components(separatedBy: \".library(name:\").count == 4)\n        #expect(manifest.components(separatedBy: \".executable(name:\").count == 2)\n    }\n\n    @Test(\"the source targets and their edges are the layer table\")\n    func layerTable() throws {\n        let sources = try manifestTargets().filter { $0.kind != \"testTarget\" }\n        #expect(Set(sources.map(\\.name)) == Set(Self.layers.keys))\n        for target in sources {\n            #expect(target.targets == Self.layers[target.name], \"\\(target.name) depends on \\(target.targets.sorted())\")\n        }\n    }\n\n    @Test(\"MLX comes only from Frigate: no mlx-swift package, Frigate taken by path\")\n    func mlxThroughFrigate() throws {\n        let manifest = try text(\"Package.swift\")\n        let url = try NSRegularExpression(pattern: #\"\\.package\\(url:\\s*\"([^\"]+)\"\"#)\n        let ns = manifest as NSString\n        let urls = url.matches(in: manifest, range: NSRange(location: 0, length: ns.length)).map { ns.substring(with: $0.range(at: 1)) }\n        #expect(!urls.isEmpty)\n        for found in urls {\n            #expect(!found.contains(\"ml-explore\") && !found.contains(\"mlx\"), \"Package.swift takes \\(found) by URL\")\n        }\n        #expect(manifest.contains(\".package(path: frigate)\"))\n    }\n\n    @Test(\"every import sits inside its target's declared dependencies\")\n    func importsAreDeclared() throws {\n        let targets = try manifestTargets()\n        let byName = Dictionary(uniqueKeysWithValues: targets.map { ($0.name, $0) })\n        func closure(_ name: String) -> Set<String> {\n            var seen: Set<String> = []\n            var stack = [name]\n            while let next = stack.popLast() {\n                for dependency in byName[next]?.targets ?? [] where !seen.contains(dependency) {\n                    seen.insert(dependency)\n                    stack.append(dependency)\n                }\n            }\n            return seen\n        }\n        for target in targets where target.kind != \"testTarget\" {\n            let directProducts = Set(target.products.map(module(ofProduct:)))\n            let layer = closure(target.name)\n            let allowedSystem = target.name == \"VeilGardeCore\" ? [\"Foundation\", \"Crypto\"] : systemModules.union([\"Crypto\"])\n            for file in swiftFiles(under: \"Sources/\\(target.name)\") {\n                let body = try String(contentsOf: file, encoding: .utf8)\n                for name in imports(in: body) {\n                    if frigateModules.contains(name) {\n                        #expect(directProducts.contains(name), \"\\(target.name)/\\(file.lastPathComponent) imports \\(name) without listing its Frigate product\")\n                    } else if name.hasPrefix(\"VeilGarde\") || name == \"VeilWatermark\" {\n                        #expect(layer.contains(name), \"\\(target.name)/\\(file.lastPathComponent) imports \\(name), above its layer\")\n                    } else if name == \"ArgumentParser\" {\n                        #expect(target.name == \"VeilGardeCLI\", \"\\(file.lastPathComponent) imports ArgumentParser outside the CLI\")\n                    } else {\n                        #expect(allowedSystem.contains(name), \"\\(target.name)/\\(file.lastPathComponent) imports \\(name)\")\n                    }\n                }\n            }\n        }\n    }\n\n    @Test(\"nothing imports MLXLLM, MLXLMCommon, UIKit or SwiftUI, and AppKit only to decode images\")\n    func noForbiddenImports() throws {\n        for file in swiftFiles(under: \"Sources\") + swiftFiles(under: \"Playground/Sources\") {\n            let names = Set(imports(in: try String(contentsOf: file, encoding: .utf8)))\n            for forbidden in [\"MLXLLM\", \"MLXLMCommon\", \"UIKit\", \"SwiftUI\"] {\n                #expect(!names.contains(forbidden), \"\\(file.lastPathComponent) imports \\(forbidden)\")\n            }\n            // NSImage is the decoder every shipped artifact was computed through (ImageDecoding's PIN).\n            if names.contains(\"AppKit\") {\n                #expect(file.path.hasSuffix(\"Sources/VeilGardeLens/Image/ImageDecoding.swift\"), \"\\(file.lastPathComponent) imports AppKit\")\n            }\n        }\n    }\n\n    @Test(\"nothing re-declares a function Frigate already provides\")\n    func noFrigateReimplementation() throws {\n        let frigateFunctions = [\n            \"perspectiveWarp\", \"getPerspectiveTransform\", \"getPerspectiveTransformD\", \"invertMatrix3x3\", \"invertMatrix3x3D\",\n            \"gaussianBlur\", \"sobelGradients\", \"filter2D\", \"batchedFilter2D\", \"batchedSobelGradients\", \"batchedGaussianBlur\",\n            \"reflect101Index\", \"reflectPad101\", \"buildBicubicWarpTapsHost\", \"buildBicubicWarpTable\", \"applyWarpTable\",\n            \"spectralDistance\", \"kmeans\", \"nearestCentroids\", \"pairwiseSquaredDistances\", \"centroidDistanceTable\", \"gaussianElimination\",\n        ]\n        let declaration = try NSRegularExpression(pattern: #\"\\bfunc\\s+(\\w+)\\s*[(<]\"#)\n        for file in swiftFiles(under: \"Sources\") {\n            let body = try String(contentsOf: file, encoding: .utf8)\n            let ns = body as NSString\n            for match in declaration.matches(in: body, range: NSRange(location: 0, length: ns.length)) {\n                let name = ns.substring(with: match.range(at: 1))\n                #expect(!frigateFunctions.contains(name), \"\\(file.lastPathComponent) declares \\(name), which Frigate provides\")\n            }\n        }\n    }\n\n    @Test(\"no type is named like a module\")\n    func names() throws {\n        let modules = Set(Self.layers.keys).union(frigateModules).union([\"Crypto\", \"ArgumentParser\"])\n        let declaration = try NSRegularExpression(pattern: #\"\\b(struct|class|enum|actor|protocol|typealias)\\s+(\\w+)\"#)\n        for file in swiftFiles(under: \"Sources\") {\n            let body = try String(contentsOf: file, encoding: .utf8)\n            let ns = body as NSString\n            for match in declaration.matches(in: body, range: NSRange(location: 0, length: ns.length)) {\n                let name = ns.substring(with: match.range(at: 2))\n                #expect(!modules.contains(name), \"\\(file.lastPathComponent) declares a type named \\(name)\")\n            }\n        }\n    }\n\n    @Test(\"Bundle.module is written in two files: the shipped bundle and the flywheel's resources\")\n    func bundleModuleInOneFile() throws {\n        for file in swiftFiles(under: \"Sources\") {\n            let body = try String(contentsOf: file, encoding: .utf8)\n            guard body.contains(\"Bundle.module\") else { continue }\n            #expect(file.path.hasSuffix(\"Sources/VeilGardeInference/Bundle/ShippedBundle.swift\") || file.path.hasSuffix(\"Sources/VeilGardeFlywheel/FlywheelResources.swift\"),\n                    \"\\(file.lastPathComponent) reads Bundle.module\")\n        }\n    }\n\n    @Test(\"every Swift file opens with its name, its target, its license and a WHAT\")\n    func headers() throws {\n        for root in [\"Sources\", \"Tests\", \"Playground/Sources\"] {\n            for file in swiftFiles(under: root) {\n                let body = try String(contentsOf: file, encoding: .utf8)\n                let target = file.deletingLastPathComponent().pathComponents\n                    .drop { $0 != (root == \"Playground/Sources\" ? \"Sources\" : root) }.dropFirst().first ?? \"\"\n                let header = \"//\\n//  \\(file.lastPathComponent)\\n//  \\(target)\\n//  \\(license)\\n//\\n//  WHAT:\"\n                #expect(body.hasPrefix(header), \"\\(file.path.replacingOccurrences(of: repoRoot.path + \"/\", with: \"\")) does not open with its WHAT header\")\n            }\n        }\n    }\n\n    @Test(\"the manifests, every script and the site's code name the GPL-3.0 at the top\")\n    func licenses() throws {\n        for manifest in [\"Package.swift\", \"Playground/Package.swift\"] {\n            let lines = try text(manifest).split(separator: \"\\n\", omittingEmptySubsequences: false)\n            #expect(lines.count > 1 && lines[1] == \"// \\(license)\", \"\\(manifest) names its license on its second line\")\n        }\n        var scripts: [String] = [\"build-metallib.sh\", \"Playground/run.sh\"]\n        for folder in [\"scripts\", \"docs/site/src\", \"docs/site/js\"] {\n            let names = (try? FileManager.default.contentsOfDirectory(atPath: repoRoot.appendingPathComponent(folder).path)) ?? []\n            scripts += names.filter { !$0.hasPrefix(\".\") && [\"sh\", \"py\", \"js\", \"command\"].contains(URL(fileURLWithPath: $0).pathExtension) }.map { \"\\(folder)/\\($0)\" }\n        }\n        #expect(scripts.count >= 13)\n        for script in scripts.sorted() {\n            let top = try text(script).split(separator: \"\\n\", omittingEmptySubsequences: false).prefix(16)\n            #expect(top.contains { $0.hasSuffix(license) }, \"\\(script) names its license near the top\")\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/ResultSurfaceTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,294]],"header":{"lines":[1,11],"target":"VeilGardeCoreTests","what":[6,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1800,"scopes":[["f","baseResult",["capture","patches"],"private",17,17,[18,72],28,null,-1,0,"a"],["f","object",["_"],"private",30,30,[30,58],32,null,-1,0,"a"],["S","ResultSurfaceTests",null,"",34,35,[35,26],265,null,-1,0,"a"],["f","semanticCannotReplaceWarp",[],"",36,37,[37,37],53,null,2,0,"a"],["f","cameraSurfaceOverridesScreenshotGuard",[],"",55,56,[56,49],70,null,2,0,"a"],["f","jsonProvenance",[],"",72,73,[73,33],86,null,2,0,"a"],["f","jsonSensorFields",[],"",88,89,[89,35],112,null,2,0,"a"],["f","sensorTrust",[],"",114,115,[115,30],126,null,2,0,"a"],["f","result",["_"],"",117,117,[117,61],122,null,7,4,"a"],["f","warpTrustIgnoresSemanticGrid",[],"",128,129,[129,40],137,null,2,0,"a"],["f","abstentions",["source"],"",139,140,[140,43],147,null,2,0,"a"],["f","rawValues",[],"",149,150,[150,28],156,null,2,0,"a"],["f","directionalGeometry",["featureCount"],"",158,159,[159,48],162,null,2,0,"a"],["f","warp19Geometry",[],"",164,165,[165,26],170,null,2,0,"a"],["f","partialWeights",[],"",172,173,[173,26],188,null,2,0,"a"],["f","sensorLane",[],"",190,191,[191,22],194,null,2,0,"a"],["f","signaturePlane",[],"",196,197,[197,26],205,null,2,0,"a"],["f","blockMeanDiverges",[],"",207,208,[208,36],223,null,2,0,"a"],["f","semanticProfiles",[],"",225,226,[226,28],233,null,2,0,"a"],["f","legacyLabel",[],"",235,236,[236,23],241,null,2,0,"a"],["f","legacySurface",[],"",243,244,[244,32],264,null,2,0,"a"],["S","RouteBatchTests",null,"",267,268,[268,23],294,null,-1,0,"a"],["f","parses",[],"",269,270,[270,25],276,null,21,0,"a"],["f","duplicate",[],"",278,279,[279,21],286,null,21,0,"a"],["f","rejects",[],"",288,289,[289,19],293,null,21,0,"a"]],"old":"","new":"//\n//  ResultSurfaceTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The public-surface laws and the schema-v2 JSON, ported from Garde's ResultSurfaceTests:\n//        semantic diagnostics never replace the warp surface; a camera route surfaces the sensor\n//        lane even when the screenshot guard owns the weighted verdict; trust never comes from an\n//        optional grid or from agreeing abstentions; the scoring geometry and base-weight laws;\n//        only `.control` commits a semantic probe; the legacy surface; the strict batch manifest.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\nprivate func baseResult(capture: CaptureSignature? = CaptureSignature(peak: 42, valid: true, nativePixels: 1_024, present: true),\n                        patches: [PatchInfo]? = nil) -> InferenceResult {\n    InferenceResult(\n        majorityPrediction: \"real\", majorityScore: 0.25, weightedPrediction: \"real\", weightedScore: 0.10,\n        patches: patches ?? [\n            PatchInfo(row: 0, col: 0, pGenerated: 0.20, weight: 0.60, x: 0, y: 0, width: 32, height: 32),\n            PatchInfo(row: 0, col: 1, pGenerated: 0.80, weight: 0.40, x: 32, y: 0, width: 32, height: 32),\n        ],\n        gridRows: 1, gridCols: 2, patchSize: 32, imageWidth: 64, imageHeight: 32,\n        decisionThreshold: 0.56, uncertainBand: 0.05, nativeScore: nil, nativeDisagreement: nil,\n        captureSignature: capture, majoritySource: .warpSensor, tileMapSource: .warpSensor)\n}\n\nprivate func object(_ data: Data) throws -> [String: Any] {\n    try #require(JSONSerialization.jsonObject(with: data) as? [String: Any])\n}\n\n@Suite(\"Result surface\")\nstruct ResultSurfaceTests {\n    @Test(\"routed semantic diagnostics cannot replace the warp surface\")\n    func semanticCannotReplaceWarp() {\n        let base = baseResult()\n        let result = PublicSurface.routed(\n            base: base, weightedPrediction: \"generated\", weightedScore: 0.91, capture: base.captureSignature!, specialists: [],\n            semanticTiles: [[0.99, 0.98]],\n            routeDiagnostics: RouteDiagnostics(route: \"camera\", warpP: 0.42, sensorRawP: base.sensorRawProbability, sensorP: base.sensorProbability,\n                                               sensorPrediction: base.sensorPrediction, semanticMajority: 0.99, semanticEvaluated: true, semanticTriggered: true))\n        #expect(result.majorityPrediction == base.majorityPrediction)\n        #expect(result.majorityScore == base.majorityScore)\n        #expect(result.majoritySource == .warpSensor && result.tileMapSource == .warpSensor)\n        #expect(result.patches.map(\\.pGenerated) == base.patches.map(\\.pGenerated))\n        #expect(result.semanticTiles == [[0.99, 0.98]])\n        #expect(result.sensorRawProbability == base.sensorRawProbability && result.sensorProbability == base.sensorProbability)\n        #expect(result.sensorPrediction == base.sensorPrediction)\n        #expect(result.routeDiagnostics?.route == \"camera\" && result.routeDiagnostics?.warpP == 0.42 && result.routeDiagnostics?.semanticTriggered == true)\n        #expect(result.weightedPrediction == \"generated\" && result.weightedScore == 0.91)\n    }\n\n    @Test(\"a camera route surfaces the sensor lane even when the screenshot guard owns the weighted verdict\")\n    func cameraSurfaceOverridesScreenshotGuard() {\n        let warp = baseResult()\n        let guarded = InferenceResult(\n            scorer: \"screenshot\", majorityPrediction: \"generated\", majorityScore: 0.88, weightedPrediction: \"generated\", weightedScore: 0.88,\n            patches: warp.patches, gridRows: warp.gridRows, gridCols: warp.gridCols, patchSize: warp.patchSize,\n            imageWidth: warp.imageWidth, imageHeight: warp.imageHeight, decisionThreshold: 0.5, uncertainBand: warp.uncertainBand,\n            nativeScore: nil, nativeDisagreement: nil, captureSignature: warp.captureSignature, isScreenshot: true,\n            majoritySource: .screenshotContent, tileMapSource: .warpSensor,\n            sensorRawProbability: 0.70, sensorProbability: 0.77, sensorPrediction: \"generated\")\n        let camera = PublicSurface.initial(base: guarded, domain: .camera, surface: .warpSensor)\n        #expect(camera.prediction == \"generated\" && camera.score == 0.77 && camera.majoritySource == .warpSensor && camera.tileMapSource == .warpSensor)\n        let screenshot = PublicSurface.initial(base: guarded, domain: .screenshot, surface: .warpSensor)\n        #expect(screenshot.prediction == guarded.majorityPrediction && screenshot.score == guarded.majorityScore && screenshot.majoritySource == .screenshotContent)\n        #expect(PublicSurface.initial(base: guarded, domain: .camera, surface: .legacySemantic).majoritySource == .screenshotContent)\n    }\n\n    @Test(\"the JSON adds provenance without removing the semantic diagnostics\")\n    func jsonProvenance() throws {\n        let base = baseResult()\n        let result = PublicSurface.routed(base: base, weightedPrediction: \"real\", weightedScore: 0.10, capture: base.captureSignature!,\n                                          specialists: [], semanticTiles: [[0.99, 0.98]])\n        let json = try object(ResultJSON.encode(result, times: [0.1], device: \"test\"))\n        #expect(json[\"schema_version\"] as? Int == 2)\n        #expect(json[\"majority_source\"] as? String == \"warp-sensor\" && json[\"tile_map_source\"] as? String == \"warp-sensor\")\n        let scores = try #require(json[\"patch_scores\"] as? [[Double]])\n        #expect(scores.count == 1 && abs(scores[0][0] - 0.20) < 1e-6 && abs(scores[0][1] - 0.80) < 1e-6)\n        let semantic = try #require(json[\"semantic_tiles\"] as? [[Double]])\n        #expect(abs(semantic[0][0] - 0.99) < 1e-6 && abs(semantic[0][1] - 0.98) < 1e-6)\n        let majority = try #require((json[\"verdict\"] as? [String: Any])?[\"majority\"] as? [String: Any])\n        #expect(majority[\"score\"] as? Double == 0.25 && majority[\"trust\"] as? String == \"high\")\n    }\n\n    @Test(\"the route JSON exposes the sensor calibration and the diagnostics\")\n    func jsonSensorFields() throws {\n        let modelHash = String(repeating: \"a\", count: 64), artifactHash = String(repeating: \"b\", count: 64)\n        let calibration = try SensorCalibrationContract(sensorVariant: \"warp40\", sensorModelSHA256: modelHash, transform: .identity,\n                                                        decisionThreshold: 0.60, uncertainBand: 0.04, nativeRoutes: [\"camera\"], artifactSHA256: artifactHash)\n        let result = InferenceResult(\n            majorityPrediction: \"generated\", majorityScore: 0.72, weightedPrediction: \"generated\", weightedScore: 0.91,\n            patches: [PatchInfo(row: 0, col: 0, pGenerated: 0.8, weight: 1, x: 0, y: 0, width: 32, height: 32)],\n            gridRows: 1, gridCols: 1, patchSize: 32, imageWidth: 32, imageHeight: 32, decisionThreshold: 0.56, uncertainBand: 0.04,\n            nativeScore: nil, nativeDisagreement: nil, captureSignature: CaptureSignature(peak: 42, valid: true, nativePixels: 1_024, present: true),\n            majoritySource: .warpSensor, tileMapSource: .warpSensor, sensorRawProbability: 0.68, sensorProbability: 0.72, sensorPrediction: \"generated\",\n            sensorCalibration: calibration, baseWarpModelSHA256: String(repeating: \"c\", count: 64), sensorWarpModelSHA256: modelHash,\n            routeDiagnostics: RouteDiagnostics(route: \"camera\", warpP: 0.83, sensorRawP: 0.68, sensorP: 0.72, sensorPrediction: \"generated\",\n                                               semanticMajority: 0.77, semanticEvaluated: true, semanticTriggered: true, semanticDecisive: false,\n                                               previewEvaluated: true, previewTriggered: false, previewDecisive: false))\n        let json = try object(ResultJSON.encode(result, times: [0.1], device: \"test\", route: \"camera\"))\n        #expect(json[\"route\"] as? String == \"camera\")\n        #expect(abs((json[\"sensor_raw_p\"] as? Double ?? 0) - 0.68) < 1e-6 && abs((json[\"sensor_p\"] as? Double ?? 0) - 0.72) < 1e-6)\n        #expect(json[\"sensor_prediction\"] as? String == \"generated\" && json[\"sensor_trust\"] as? String == \"high\")\n        #expect(json[\"base_model_sha256\"] as? String == String(repeating: \"c\", count: 64) && json[\"sensor_model_sha256\"] as? String == modelHash)\n        #expect(json[\"sensor_calibration_identity\"] as? String == \"identity\" && json[\"sensor_calibration_sha256\"] as? String == artifactHash)\n        let diagnostics = try #require(json[\"route_diagnostics\"] as? [String: Any])\n        #expect(abs((diagnostics[\"warp_p\"] as? Double ?? 0) - 0.83) < 1e-6)\n        #expect(diagnostics[\"semantic_evaluated\"] as? Bool == true && diagnostics[\"preview_decisive\"] as? Bool == false)\n    }\n\n    @Test(\"sensor trust rejects a non-native route and an abstention\")\n    func sensorTrust() throws {\n        let calibration = try SensorCalibrationContract.identityFallback(sensorVariant: \"warp19\", sensorModelSHA256: String(repeating: \"a\", count: 64), uncertainBand: 0.04)\n        func result(_ prediction: String) -> InferenceResult {\n            InferenceResult(majorityPrediction: prediction, majorityScore: 0.5, weightedPrediction: \"generated\", weightedScore: 0.9, patches: [],\n                            gridRows: 0, gridCols: 0, patchSize: 32, imageWidth: 1, imageHeight: 1, decisionThreshold: 0.56, uncertainBand: 0.04,\n                            nativeScore: nil, nativeDisagreement: nil, captureSignature: CaptureSignature(peak: 42, valid: true, nativePixels: 1_024, present: true),\n                            sensorRawProbability: 0.5, sensorProbability: 0.5, sensorPrediction: prediction, sensorCalibration: calibration)\n        }\n        #expect(Trust.sensorVote(result(\"generated\"), route: \"screenshot\") == \"low\")\n        #expect(Trust.sensorVote(result(\"inconclusive\"), route: \"camera\") == \"low\")\n        #expect(Trust.sensorVote(result(\"generated\"), route: \"camera\") == \"high\")\n    }\n\n    @Test(\"warp trust never infers semantic provenance from an optional grid\")\n    func warpTrustIgnoresSemanticGrid() {\n        let base = baseResult(capture: nil)\n        let result = InferenceResult(majorityPrediction: base.majorityPrediction, majorityScore: base.majorityScore, weightedPrediction: base.weightedPrediction,\n                                     weightedScore: base.weightedScore, patches: base.patches, gridRows: base.gridRows, gridCols: base.gridCols,\n                                     patchSize: base.patchSize, imageWidth: base.imageWidth, imageHeight: base.imageHeight,\n                                     decisionThreshold: base.decisionThreshold, uncertainBand: base.uncertainBand, nativeScore: nil, nativeDisagreement: nil,\n                                     semanticTiles: [[0.01]], majoritySource: .warpSensor, tileMapSource: .warpSensor)\n        #expect(Trust.physicsVote(result) == \"low\")\n    }\n\n    @Test(\"matching abstentions are never high trust\", arguments: [ResultSource.warpSensor, .screenshotContent, .semanticTiles])\n    func abstentions(source: ResultSource) {\n        let result = InferenceResult(majorityPrediction: \"inconclusive\", majorityScore: 0.50, weightedPrediction: \"inconclusive\", weightedScore: 0.50,\n                                     patches: [], gridRows: 0, gridCols: 0, patchSize: 0, imageWidth: 1, imageHeight: 1, decisionThreshold: 0.50,\n                                     uncertainBand: 0.05, nativeScore: nil, nativeDisagreement: nil,\n                                     captureSignature: CaptureSignature(peak: 42, valid: true, nativePixels: 1_024, present: true),\n                                     majoritySource: source, tileMapSource: .none)\n        #expect(Trust.physicsVote(result) == \"low\")\n    }\n\n    @Test(\"campaign raw values are stable and round-trip\")\n    func rawValues() throws {\n        #expect(try JSONDecoder().decode(ResultSource.self, from: JSONEncoder().encode(ResultSource.warpSensor)) == .warpSensor)\n        #expect(SemanticResponsibility.semanticDiagnosticOnly.rawValue == \"semantic_diagnostic_only\")\n        #expect(SemanticResponsibility.semanticRemoved.rawValue == \"semantic_removed\")\n        #expect(ResultSurface.legacySemantic.rawValue == \"legacy-semantic\")\n        #expect(try JSONDecoder().decode(SemanticResponsibility.self, from: JSONEncoder().encode(SemanticResponsibility.semanticRemoved)) == .semanticRemoved)\n    }\n\n    @Test(\"directional scoring geometry keeps the remainder in the presentation canvas\", arguments: [35, 40])\n    func directionalGeometry(featureCount: Int) {\n        let g = ScoringGeometry.make(realWidth: 512, realHeight: 341, paddedWidth: 512, paddedHeight: 352, featureCount: featureCount)\n        #expect(g.imageWidth == 512 && g.imageHeight == 341 && g.scoringWidth == 512 && g.scoringHeight == 320)\n    }\n\n    @Test(\"scoring geometry keeps aligned and 19-column behaviour\")\n    func warp19Geometry() {\n        #expect(ScoringGeometry.make(realWidth: 512, realHeight: 320, paddedWidth: 512, paddedHeight: 320, featureCount: 40)\n                == ScoringGeometry(imageWidth: 512, imageHeight: 320, scoringWidth: 512, scoringHeight: 320))\n        #expect(ScoringGeometry.make(realWidth: 512, realHeight: 341, paddedWidth: 512, paddedHeight: 352, featureCount: 19)\n                == ScoringGeometry(imageWidth: 512, imageHeight: 341, scoringWidth: 512, scoringHeight: 352))\n    }\n\n    @Test(\"partial base-weight contributions are not renormalized\")\n    func partialWeights() {\n        let baseWeights: [[Float]] = [[0.4, 0.1], [0.2, 0.3]]\n        var partial: Float = 0\n        for y in stride(from: 0, to: 96, by: 32) { for x in stride(from: 0, to: 96, by: 32) {\n            partial += ScoringGeometry.baseWeightContribution(weightMap: baseWeights, x: x, y: y, basePatchSize: 64, sensorPatchSize: 32)\n        } }\n        #expect(abs(partial - 0.625) < 1e-6)\n        var full: Float = 0\n        for y in stride(from: 0, to: 128, by: 32) { for x in stride(from: 0, to: 128, by: 32) {\n            full += ScoringGeometry.baseWeightContribution(weightMap: baseWeights, x: x, y: y, basePatchSize: 64, sensorPatchSize: 32)\n        } }\n        #expect(abs(full - 1) < 1e-6)\n        let r = baseResult(patches: [PatchInfo(row: 0, col: 0, pGenerated: 0.20, weight: 0.25, x: 0, y: 0, width: 32, height: 32),\n                                     PatchInfo(row: 0, col: 1, pGenerated: 0.80, weight: 0.375, x: 32, y: 0, width: 32, height: 32)])\n        #expect(abs(r.visibleBaseWeightShare - 0.625) < 1e-6)\n    }\n\n    @Test(\"the sensor lane is the 32-px tile grid, never a presentation patch size\")\n    func sensorLane() {\n        #expect(ScoringGeometry.baseGridIsSensorLane(patchSize: 32))\n        for size in [64, 128, 256] { #expect(!ScoringGeometry.baseGridIsSensorLane(patchSize: size)) }\n    }\n\n    @Test(\"the unpadded plane covers only truncated signature grids\")\n    func signaturePlane() {\n        #expect(ScoringGeometry.unpaddedPlaneCoversSignatureGrid(sigH: 341, sigW: 512, TR: 10, TC: 16))\n        #expect(ScoringGeometry.unpaddedPlaneCoversSignatureGrid(sigH: 128, sigW: 512, TR: 4, TC: 16))\n        #expect(!ScoringGeometry.unpaddedPlaneCoversSignatureGrid(sigH: 120, sigW: 512, TR: 4, TC: 16))\n        #expect(!ScoringGeometry.unpaddedPlaneCoversSignatureGrid(sigH: 512, sigW: 120, TR: 16, TC: 4))\n        #expect(ScoringGeometry.unpaddedPlaneCoversSignatureGrid(sigH: 128, sigW: 480, TR: 4, TC: 15))\n        #expect(!ScoringGeometry.unpaddedPlaneCoversSignatureGrid(sigH: 127, sigW: 480, TR: 4, TC: 15))\n        #expect(!ScoringGeometry.unpaddedPlaneCoversSignatureGrid(sigH: 0, sigW: 0, TR: 1, TC: 1))\n    }\n\n    @Test(\"a block-mean fraction diverges from the tile fraction at the operating point\")\n    func blockMeanDiverges() throws {\n        let contract = try SensorCalibrationContract(sensorVariant: \"warp19\", sensorModelSHA256: String(repeating: \"a\", count: 64), transform: .platt,\n                                                     plattPayload: SensorPlattPayload(coef: 0.48908749922126266, intercept: -0.09094760943132153),\n                                                     decisionThreshold: 0.6298664647384551, uncertainBand: 0.04)\n        var tiles = [[Float]](repeating: [Float](repeating: 0.51, count: 4), count: 4)\n        for i in 0..<2 { for j in 0..<2 { tiles[i * 2][j * 2] = 0.20 } }\n        let tileFraction = Float(tiles.flatMap { $0 }.filter { $0 > 0.5 }.count) / 16\n        var blockMeans = [Float]()\n        for i in stride(from: 0, to: 4, by: 2) { for j in stride(from: 0, to: 4, by: 2) {\n            blockMeans.append((tiles[i][j] + tiles[i][j + 1] + tiles[i + 1][j] + tiles[i + 1][j + 1]) / 4)\n        } }\n        let blockFraction = Float(blockMeans.filter { $0 > 0.5 }.count) / Float(blockMeans.count)\n        #expect(abs(tileFraction - 0.75) < 1e-6 && abs(blockFraction) < 1e-6)\n        #expect(contract.prediction(for: contract.calibratedProbability(tileFraction)) == \"inconclusive\")\n        #expect(contract.prediction(for: contract.calibratedProbability(blockFraction)) == \"real\")\n    }\n\n    @Test(\"only the control profile commits a semantic probe\")\n    func semanticProfiles() {\n        let control = PublicSurface.project(profile: .control, originalP: 0.20, originalVerdict: \"real\", probeP: 0.90, probeVerdict: \"generated\", probeDecisive: true)\n        #expect(control == SemanticProjection(p: 0.90, verdict: \"generated\", decisive: true))\n        for profile in [SemanticResponsibility.semanticDiagnosticOnly, .semanticRemoved] {\n            let projected = PublicSurface.project(profile: profile, originalP: 0.20, originalVerdict: \"real\", probeP: 0.90, probeVerdict: \"generated\", probeDecisive: true)\n            #expect(projected == SemanticProjection(p: 0.20, verdict: \"real\", decisive: false))\n        }\n    }\n\n    @Test(\"the legacy semantic label: render, then the domain gate, then coherence\")\n    func legacyLabel() {\n        #expect(PublicSurface.legacySemanticPrediction(semanticVerdict: \"generated\", weightedVerdict: \"real\", renderFires: true, domainGated: true) == \"render\")\n        #expect(PublicSurface.legacySemanticPrediction(semanticVerdict: \"generated\", weightedVerdict: \"generated\", renderFires: false, domainGated: true) == \"inconclusive\")\n        #expect(PublicSurface.legacySemanticPrediction(semanticVerdict: \"generated\", weightedVerdict: \"generated\", renderFires: false, domainGated: false) == \"generated\")\n        #expect(PublicSurface.legacySemanticPrediction(semanticVerdict: \"generated\", weightedVerdict: \"real\", renderFires: false, domainGated: false) == \"inconclusive\")\n    }\n\n    @Test(\"the legacy surface selects the semantic map and keeps the warp patches\")\n    func legacySurface() throws {\n        let base = baseResult()\n        let diagnostics = RouteDiagnostics(route: \"camera\", requestedHint: \"camera\", semanticProfile: SemanticResponsibility.semanticDiagnosticOnly.rawValue,\n                                           resultSurface: ResultSurface.legacySemantic.rawValue, preSemanticP: 0.37, preSemanticPrediction: \"real\",\n                                           semanticMajority: 1.0, semanticEvaluated: true, semanticTriggered: true, semanticDecisive: false)\n        let result = PublicSurface.routed(base: base, weightedPrediction: \"generated\", weightedScore: 0.91, capture: base.captureSignature!, specialists: [],\n                                          semanticTiles: [[0.99], [0.98]], majorityPrediction: \"generated\", majorityScore: 1.0,\n                                          majoritySource: .semanticTiles, tileMapSource: .semanticTiles, routeDiagnostics: diagnostics)\n        #expect(result.majoritySource == .semanticTiles && result.tileMapSource == .semanticTiles)\n        #expect(result.patches.map(\\.pGenerated) == base.patches.map(\\.pGenerated))\n        let json = try object(ResultJSON.encode(result, times: [], device: \"test\"))\n        let grid = try #require(json[\"grid\"] as? [String: Int])\n        #expect(grid[\"rows\"] == 2 && grid[\"cols\"] == 1)\n        #expect(abs((try #require(json[\"patch_scores\"] as? [[Double]]))[0][0] - 0.99) < 1e-6)\n        let warp = try #require(json[\"warp_patch_scores\"] as? [[Double]])\n        #expect(abs(warp[0][0] - 0.20) < 1e-6 && abs(warp[0][1] - 0.80) < 1e-6)\n        let trace = try #require(json[\"route_diagnostics\"] as? [String: Any])\n        #expect(trace[\"requested_hint\"] as? String == \"camera\" && trace[\"semantic_profile\"] as? String == \"semantic_diagnostic_only\")\n        #expect(trace[\"result_surface\"] as? String == \"legacy-semantic\" && trace[\"pre_semantic_prediction\"] as? String == \"real\")\n        #expect(abs((trace[\"pre_semantic_p\"] as? Double ?? 0) - 0.37) < 1e-6 && trace[\"semantic_decisive\"] as? Bool == false)\n    }\n}\n\n@Suite(\"Route batch manifest\")\nstruct RouteBatchTests {\n    @Test(\"parses order and hints exactly\")\n    func parses() throws {\n        let items = try RouteBatch.parse(Data(\"\"\"\n        {\"id\":\"first\",\"path\":\"/a.jpg\",\"hint\":\"camera\"}\n        {\"id\":\"second\",\"path\":\"/b.png\",\"hint\":\"screenshot\"}\n        \"\"\".utf8))\n        #expect(items.map(\\.id) == [\"first\", \"second\"] && items.map(\\.hint) == [.camera, .screenshot])\n    }\n\n    @Test(\"rejects a duplicate id before inference\")\n    func duplicate() {\n        #expect(throws: RouteBatchError.duplicateID(line: 2, id: \"same\")) {\n            try RouteBatch.parse(Data(\"\"\"\n            {\"id\":\"same\",\"path\":\"/a.jpg\",\"hint\":\"camera\"}\n            {\"id\":\"same\",\"path\":\"/b.jpg\",\"hint\":\"camera\"}\n            \"\"\".utf8))\n        }\n    }\n\n    @Test(\"rejects a bad id, hint or shape\")\n    func rejects() {\n        #expect(throws: RouteBatchError.self) { try RouteBatch.parse(Data(#\"{\"id\":\"bad id \",\"path\":\"/a\",\"hint\":\"camera\"}\"#.utf8)) }\n        #expect(throws: RouteBatchError.self) { try RouteBatch.parse(Data(#\"{\"id\":\"a\",\"path\":\"/a\",\"hint\":\"auto\"}\"#.utf8)) }\n        #expect(throws: RouteBatchError.self) { try RouteBatch.parse(Data(#\"{\"id\":\"a\",\"path\":\"/a\",\"hint\":\"camera\",\"extra\":1}\"#.utf8)) }\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/SafetensorsLayoutTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,54]],"header":{"lines":[1,10],"target":"VeilGardeCoreTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1825,"scopes":[["S","SafetensorsLayoutTests",null,"",16,17,[17,30],54,null,-1,0,"a"],["f","fixture",[],"",18,19,[19,26],35,null,0,0,"a"],["f","shipped",["_"],"static",38,38,[38,48],43,[37,37],0,0,"a"],["f","shippedFiles",["_"],"",45,46,[46,45],53,null,0,0,"a"]],"old":"","new":"//\n//  SafetensorsLayoutTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The writer's python layout writes the bytes Python's safetensors writes: a committed\n//        file from safetensors 0.5 (six dtypes) is reproduced exactly, and so, when this Mac\n//        has them, are the shipped weight files exported from Python (the noiseprint and DINOv2-small),\n//        re-encoded from their own tensors. That is what lets an import be byte-identical.\n//\n\nimport Foundation\nimport Testing\nimport VeilGardeCore\n\n@Suite(\"Safetensors: Python's own layout\")\nstruct SafetensorsLayoutTests {\n    @Test(\"a file Python's safetensors wrote is reproduced byte for byte\")\n    func fixture() throws {\n        let entries: [SafetensorsWriter.Entry] = [\n            .init(\"b_u8\", shape: [5], .uint8([0, 1, 127, 254, 255])),\n            .init(\"s_i16\", shape: [2], .int16([-300, 300])),\n            .init(\"h_f16\", shape: [3], .float16Bits([0x3C00, 0xC000, 0x3800])),\n            .init(\"m_i32\", shape: [1], .int32([-7])),\n            .init(\"a_u32\", shape: [2], .uint32([1, 4_294_967_295])),\n            .init(\"z_f32\", shape: [1], .float32([-0.0])),\n            .init(\"w_f32\", shape: [2, 3], .float32([0, 1.5, -2, 3.25, 1e-3, 7])),\n        ]\n        let expected = try Data(contentsOf: Fixture.url(\"python_layout.safetensors\"))\n        #expect(try SafetensorsWriter.encode(entries, layout: .python) == expected)\n        #expect(try SafetensorsWriter.encode(entries.reversed(), layout: .python) == expected, \"the order the entries come in does not matter\")\n        let read = try SafetensorsFile(data: expected)\n        #expect(try read.uint32(\"a_u32\") == [1, 4_294_967_295])\n        #expect(try read.bytes(\"b_u8\") == Data([0, 1, 127, 254, 255]))\n    }\n\n    /// A shipped weight file exported with Python's safetensors, when this Mac has one.\n    static func shipped(_ name: String) -> URL? {\n        var folders: [URL] = []\n        if let named = ProcessInfo.processInfo.environment[\"VEILGARDE_WEIGHTS\"] { folders.append(URL(fileURLWithPath: named)) }\n        if let area = WorkArea.resolve() { folders.append(area.weights) }\n        return folders.map { $0.appendingPathComponent(name) }.first { FileManager.default.fileExists(atPath: $0.path) }\n    }\n\n    @Test(\"the shipped weights re-encode to their own bytes\", arguments: [\"noiseprint_v1.safetensors\", \"dinov2_small.safetensors\"])\n    func shippedFiles(_ name: String) throws {\n        guard let url = Self.shipped(name) else { return }\n        let file = try SafetensorsFile(url: url)\n        let entries = try file.names.map { SafetensorsWriter.Entry($0, shape: try file.tensor($0).shape, .float32(try file.float32($0))) }\n        let data = try SafetensorsWriter.encode(entries, layout: .python)\n        #expect(data.count == file.data.count)\n        #expect(data == file.data, \"\\(name) re-encoded differs from the file\")\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/SensorCalibrationTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,170]],"header":{"lines":[1,12],"target":"VeilGardeCoreTests","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1829,"scopes":[["S","SensorCalibrationTests",null,"",18,19,[19,30],170,null,-1,0,"a"],["f","shippedPair",[],"",22,23,[23,30],40,null,0,0,"a"],["f","gardePlatt",["_"],"static",43,43,[43,78],47,[42,42],0,0,"a"],["f","cutsEqualPlatt",[],"",49,50,[50,33],70,null,0,0,"a"],["f","same",["_"],"",56,56,[56,38],56,null,3,12,"a"],["f","degenerateCuts",[],"",72,73,[73,33],84,null,0,0,"a"],["f","cutsRefused",[],"",86,87,[87,30],104,null,0,0,"a"],["f","json",["schema","calibration","lo","hi","t","band","comparison"],"",88,88,[89,76],97,null,6,4,"a"],["f","identityFallback",[],"",106,107,[107,35],117,null,0,0,"a"],["f","plattScale",[],"",119,120,[120,29],126,null,0,0,"a"],["f","decodeBinds",[],"",128,129,[129,30],147,null,0,0,"a"],["f","fileForm",[],"",149,150,[150,27],161,null,0,0,"a"],["f","variants",[],"",163,164,[164,27],169,null,0,0,"a"]],"old":"","new":"//\n//  SensorCalibrationTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The camera-sensor contract: the shipped pair is bound to the sensor model's bytes, and its\n//        two cuts call every float32 vote as Garde's Platt contract did; a cuts file states its cuts'\n//        own midpoint and band or is refused. Ported from Garde's SensorCalibrationTests: the\n//        identity fallback keeps the raw fraction with an open band and Garde's provenance hash;\n//        Platt is on the logit scale; decoding binds model and variant; the trainer's file form\n//        decodes back.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Sensor calibration\")\nstruct SensorCalibrationTests {\n    let modelHash = String(repeating: \"a\", count: 64)\n\n    @Test(\"the shipped sensor and its calibration are a bound pair with the deployed operating point\")\n    func shippedPair() throws {\n        let modelSHA = try ContentHash.sha256Hex(fileAt: Fixture.resource(\"warp_majority_tile32.xgb.json\"))\n        #expect(modelSHA == \"516119c92d364dda3dba41dcfc42e06edf0f42e45efd3b54c44ab620f7eefe3d\")\n        let calibration = try SensorCalibrationContract.decode(\n            Data(contentsOf: Fixture.resource(\"warp_sensor_calibration.json\")), expectedModelSHA256: modelSHA, expectedSensorVariant: \"warp19\")\n        #expect(calibration.transform == .cuts && calibration.schema == 2 && calibration.comparison == \"at_or_above_generated_cut\")\n        #expect(calibration.nativeRoutes == [\"camera\"])\n        #expect(calibration.artifactSHA256 != nil)\n        #expect(calibration.calibratedProbability(0.42) == 0.42, \"the score is the tile vote itself\")\n        #expect(calibration.prediction(for: calibration.calibratedProbability(0.90)) == \"generated\")\n        #expect(calibration.prediction(for: calibration.calibratedProbability(0.78)) == \"inconclusive\")\n        #expect(calibration.prediction(for: calibration.calibratedProbability(0.50)) == \"real\")\n        let cuts = try #require(calibration.cuts)\n        let lo = Float(cuts.realAtOrBelow), hi = Float(cuts.generatedAtOrAbove)\n        #expect(Double(lo) == cuts.realAtOrBelow && Double(hi) == cuts.generatedAtOrAbove, \"each cut is a float32 vote\")\n        #expect(calibration.prediction(for: lo) == \"real\" && calibration.prediction(for: lo.nextUp) == \"inconclusive\")\n        #expect(calibration.prediction(for: hi) == \"generated\" && calibration.prediction(for: hi.nextDown) == \"inconclusive\")\n    }\n\n    /// Garde's shipped Platt contract, the one the shipped cuts replace.\n    static func gardePlatt(_ sha: String) throws -> SensorCalibrationContract {\n        try SensorCalibrationContract(sensorVariant: \"warp19\", sensorModelSHA256: sha, transform: .platt,\n                                      plattPayload: SensorPlattPayload(coef: 0.48908749922126266, intercept: -0.09094760943132153),\n                                      decisionThreshold: Float(0.6298664647384551), uncertainBand: 0.04)\n    }\n\n    @Test(\"the shipped cuts are where Garde's Platt contract turns, and call every vote as it did\")\n    func cutsEqualPlatt() throws {\n        let sha = \"516119c92d364dda3dba41dcfc42e06edf0f42e45efd3b54c44ab620f7eefe3d\"\n        let platt = try Self.gardePlatt(sha)\n        let shipped = try SensorCalibrationContract.decode(Data(contentsOf: Fixture.resource(\"warp_sensor_calibration.json\")),\n                                                           expectedModelSHA256: sha, expectedSensorVariant: \"warp19\")\n        #expect(platt.equivalentCuts() == shipped.cuts)\n        func same(_ v: Float) -> Bool { shipped.prediction(for: shipped.calibratedProbability(v)) == platt.prediction(for: platt.calibratedProbability(v)) }\n        var votes = 0, differ = 0\n        for n in 1...1024 {\n            for k in 0...n {\n                votes += 1\n                if !same(Float(k) / Float(n)) { differ += 1 }\n            }\n        }\n        #expect(differ == 0, \"\\(differ) of \\(votes) votes k/n (n ≤ 1024) called differently\")\n        let cuts = try #require(shipped.cuts)\n        for v in [Float(cuts.realAtOrBelow), Float(cuts.generatedAtOrAbove)] { #expect(same(v) && same(v.nextUp) && same(v.nextDown)) }\n        let file = try #require(SensorCalibrationFile.twoCuts(from: platt))\n        let written = try SensorCalibrationContract.decode(try JSONCoding.prettyEncoder().encode(file), expectedModelSHA256: sha, expectedSensorVariant: \"warp19\")\n        #expect(written.cuts == shipped.cuts && file.derivedFrom?.plattPayload?.coef == 0.48908749922126266)\n    }\n\n    @Test(\"a contract that never calls one side gets a cut that never fires, and calls as before\")\n    func degenerateCuts() throws {\n        // σ(logit v) is v itself; T 0.01 ± 0.04 leaves no vote real.\n        let never = try SensorCalibrationContract(sensorVariant: \"warp19\", sensorModelSHA256: modelHash, transform: .platt,\n                                                  plattPayload: SensorPlattPayload(coef: 1, intercept: 0), decisionThreshold: 0.01, uncertainBand: 0.04)\n        let cuts = never.equivalentCuts()\n        #expect(cuts.realAtOrBelow == -1 && cuts.generatedAtOrAbove > 0.049 && cuts.generatedAtOrAbove < 0.051)\n        let file = try #require(SensorCalibrationFile.twoCuts(from: never))\n        let back = try SensorCalibrationContract.decode(try JSONCoding.prettyEncoder().encode(file), expectedModelSHA256: modelHash, expectedSensorVariant: \"warp19\")\n        var differ = 0\n        for n in 1...256 { for k in 0...n where back.prediction(for: Float(k) / Float(n)) != never.prediction(for: never.calibratedProbability(Float(k) / Float(n))) { differ += 1 } }\n        #expect(differ == 0 && back.prediction(for: 0) == \"inconclusive\")\n    }\n\n    @Test(\"a cuts file is refused when its band is not its cuts', its cuts are out of order, or its schema is not 2\")\n    func cutsRefused() throws {\n        func json(schema: Int = 2, calibration: String = \"cuts\", lo: Double = 0.7, hi: Double = 0.8, t: Double = 0.75, band: Double = 0.05,\n                  comparison: String = \"at_or_above_generated_cut\") -> Data {\n            Data(\"\"\"\n            {\"schema_version\": \\(schema), \"sensor_variant\": \"warp19\", \"sensor_model_sha256\": \"\\(modelHash)\",\n             \"score_semantics\": \"image_majority_fraction\", \"calibration\": \"\\(calibration)\", \"platt_payload\": null,\n             \"cuts\": {\"real_at_or_below\": \\(lo), \"generated_at_or_above\": \\(hi)},\n             \"decision_threshold\": \\(t), \"uncertain_band\": \\(band), \"generated_comparison\": \"\\(comparison)\",\n             \"native_routes\": [\"camera\"], \"trust_law\": \"v1_decisive_native_capture_present_valid_and_governing_agreement\"}\n            \"\"\".utf8)\n        }\n        let ok = try SensorCalibrationContract.decode(json(), expectedModelSHA256: modelHash, expectedSensorVariant: \"warp19\")\n        #expect(ok.prediction(for: 0.7) == \"real\" && ok.prediction(for: 0.75) == \"inconclusive\" && ok.prediction(for: 0.8) == \"generated\")\n        for bad in [json(t: 0.76), json(band: 0.04), json(lo: 0.8, hi: 0.7, t: 0.75, band: -0.05), json(schema: 1),\n                    json(comparison: \"strictly_greater_than_threshold\"), json(calibration: \"identity\")] {\n            #expect(throws: SensorCalibrationError.self) { try SensorCalibrationContract.decode(bad, expectedModelSHA256: modelHash, expectedSensorVariant: \"warp19\") }\n        }\n    }\n\n    @Test(\"the identity fallback keeps the raw fraction, an open band and Garde's provenance hash\")\n    func identityFallback() throws {\n        let calibration = try SensorCalibrationContract.identityFallback(sensorVariant: \"warp19\", sensorModelSHA256: modelHash, uncertainBand: 0.25)\n        #expect(calibration.identity == \"identity-fallback\")\n        #expect(calibration.artifactSHA256 == nil)\n        #expect(calibration.calibratedProbability(0.37) == 0.37)\n        #expect(calibration.prediction(for: 0.50) == \"inconclusive\")\n        #expect(calibration.prediction(for: 0.25) == \"real\")\n        #expect(calibration.prediction(for: 0.75) == \"generated\")\n        let campaign = try SensorCalibrationContract.identityFallback(sensorVariant: \"warp19\", sensorModelSHA256: modelHash, uncertainBand: 0.04)\n        #expect(campaign.provenanceSHA256 == \"2fc3428e1db2bb7a78e3b361febd1547098657be5634a106e34a39cf3fc2cf51\")\n    }\n\n    @Test(\"Platt works on the logit scale\")\n    func plattScale() throws {\n        let calibration = try SensorCalibrationContract(sensorVariant: \"warp40\", sensorModelSHA256: modelHash, transform: .platt,\n                                                        plattPayload: SensorPlattPayload(coef: 2, intercept: 0), decisionThreshold: 0.7,\n                                                        uncertainBand: 0.04, artifactSHA256: String(repeating: \"b\", count: 64))\n        #expect(abs(calibration.calibratedProbability(0.8) - 16.0 / 17.0) < 1e-6)   // σ(2·logit 0.8)\n        #expect(calibration.prediction(for: calibration.calibratedProbability(0.8)) == \"generated\")\n    }\n\n    @Test(\"decoding binds the exact model and variant\")\n    func decodeBinds() throws {\n        let json = \"\"\"\n        {\"schema_version\": 1, \"sensor_variant\": \"warp19_e16\", \"sensor_model_sha256\": \"\\(modelHash)\",\n         \"score_semantics\": \"image_majority_fraction\", \"calibration\": \"identity\", \"platt_payload\": null,\n         \"decision_threshold\": 0.61, \"uncertain_band\": 0.04, \"generated_comparison\": \"strictly_greater_than_threshold\",\n         \"native_routes\": [\"camera\"], \"trust_law\": \"v1_decisive_native_capture_present_valid_and_governing_agreement\"}\n        \"\"\"\n        let data = Data(json.utf8)\n        let calibration = try SensorCalibrationContract.decode(data, expectedModelSHA256: modelHash, expectedSensorVariant: \"warp19_e16\")\n        #expect(calibration.transform == .identity)\n        #expect(abs(calibration.decisionThreshold - 0.61) < 1e-6)\n        #expect(calibration.artifactSHA256?.count == 64)\n        #expect(throws: SensorCalibrationError.self) {\n            try SensorCalibrationContract.decode(data, expectedModelSHA256: String(repeating: \"c\", count: 64), expectedSensorVariant: \"warp19_e16\")\n        }\n        #expect(throws: SensorCalibrationError.variantMismatch(expected: \"warp19_e16\", actual: \"warp40\")) {\n            try SensorCalibrationContract.decode(data, expectedModelSHA256: modelHash, expectedSensorVariant: \"warp40\")\n        }\n    }\n\n    @Test(\"a written SensorCalibrationFile decodes as a valid contract\")\n    func fileForm() throws {\n        let file = SensorCalibrationFile(sensorVariant: \"warp19\", sensorModelSHA256: modelHash, calibration: .platt,\n                                         plattPayload: SensorPlattPayload(coef: 0.48908749922126266, intercept: -0.09094760943132153),\n                                         decisionThreshold: 0.6298664647384551, uncertainBand: 0.04)\n        let data = try JSONCoding.prettyEncoder().encode(file)\n        let contract = try SensorCalibrationContract.decode(data, expectedModelSHA256: modelHash, expectedSensorVariant: \"warp19\")\n        #expect(contract.transform == .platt && contract.plattPayload?.coef == 0.48908749922126266)\n        let identity = SensorCalibrationFile(sensorVariant: \"warp19\", sensorModelSHA256: modelHash, calibration: .identity,\n                                             plattPayload: nil, decisionThreshold: 0.5, uncertainBand: 0.04)\n        let text = String(decoding: try JSONCoding.prettyEncoder().encode(identity), as: UTF8.self)\n        #expect(text.contains(\"\\\"platt_payload\\\" : null\"))\n    }\n\n    @Test(\"column counts name the sensor variants\")\n    func variants() throws {\n        #expect(try SensorCalibrationContract.variant(featureCount: 19) == \"warp19\")\n        #expect(try SensorCalibrationContract.variant(featureCount: 35) == \"warp19_e16\")\n        #expect(try SensorCalibrationContract.variant(featureCount: 40) == \"warp40\")\n        #expect(throws: SensorCalibrationError.self) { try SensorCalibrationContract.variant(featureCount: 12) }\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/StoreTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,75]],"header":{"lines":[1,8],"target":"VeilGardeCoreTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1842,"scopes":[["S","StoreTests",null,"",14,15,[15,18],75,null,-1,0,"a"],["f","tempDirectory",[],"",16,16,[16,39],20,null,0,0,"a"],["f","shard",["_","ids","label"],"",22,22,[22,74],29,null,0,0,"a"],["f","roundTrip",[],"",31,32,[32,28],43,null,0,0,"a"],["f","selection",[],"",45,46,[46,28],64,null,0,0,"a"],["f","readsRa",[],"",66,67,[67,26],74,null,0,0,"a"]],"old":"","new":"//\n//  StoreTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The features-only store: a shard round-trips its rows and columns, is never overwritten,\n//        reads the seed store's shards as they were written, and a selection filters, keeps or drops duplicates, and stacks.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Feature store\")\nstruct StoreTests {\n    func tempDirectory() throws -> URL {\n        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-store-\\(UUID().uuidString)\")\n        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)\n        return dir\n    }\n\n    func shard(_ name: String, ids: [String], label: Int) -> FeatureShard {\n        let rows = ids.map { FeatureRow(id: $0, path: \"/x/\\($0).jpg\", label: label, category: \"art\", source: \"test\", warpModel: \"516119c92d36\") }\n        var columns: [FeatureColumn: [Float]] = [:]\n        for column in FeatureColumn.allCases {\n            columns[column] = (0..<(ids.count * column.width)).map { Float($0) + (label == 1 ? 0.5 : 0) }\n        }\n        return FeatureShard(name: name, rows: rows, columns: columns, metadata: [\"warp_model_sha256\": \"516119c9\"])\n    }\n\n    @Test(\"a shard round-trips and is never overwritten\")\n    func roundTrip() throws {\n        let dir = try tempDirectory()\n        defer { try? FileManager.default.removeItem(at: dir) }\n        let written = shard(\"s1\", ids: [\"a\", \"b\", \"c\"], label: 1)\n        try written.write(to: dir)\n        let read = try FeatureShard.read(\"s1\", in: dir)\n        #expect(read.rows == written.rows)\n        #expect(read.columns == written.columns)\n        #expect(read.metadata[\"format\"] == FeatureShard.format && read.metadata[\"warp_model_sha256\"] == \"516119c9\")\n        #expect(Array(read.vector(.cap, row: 1)) == (9..<18).map { Float($0) + 0.5 })\n        #expect(throws: VeilGardeFailure.self) { try written.write(to: dir) }\n    }\n\n    @Test(\"a selection keeps duplicates as the Python store does, dedups on request, filters, and stacks the fusion columns\")\n    func selection() throws {\n        let dir = try tempDirectory()\n        defer { try? FileManager.default.removeItem(at: dir) }\n        try shard(\"a_first\", ids: [\"x\", \"y\"], label: 1).write(to: dir)\n        try shard(\"b_second\", ids: [\"y\", \"z\"], label: 0).write(to: dir)\n        let store = FeatureStore(directory: dir)\n        #expect(store.shardNames() == [\"a_first\", \"b_second\"])\n        #expect(try store.select(columns: [.warp]).rows.map(\\.id) == [\"x\", \"y\", \"y\", \"z\"])\n        let all = try store.select(columns: Set(FeatureColumn.fusion), dedup: true)\n        #expect(all.rows.map(\\.id) == [\"x\", \"y\", \"z\"])\n        #expect(all.shards == [\"a_first\", \"a_first\", \"b_second\"])\n        let fusion = all.matrix(FeatureColumn.fusion)\n        #expect(fusion.count == 3 * 397)\n        #expect(fusion[0] == 0.5)                 // x's warp\n        #expect(fusion[397 * 2] == 1)             // z's warp (row 1 of b_second)\n        let reals = all.filter { !$0.isGenerated }\n        #expect(reals.rows.map(\\.id) == [\"z\"])\n        #expect(try store.ids() == [\"x\", \"y\", \"z\"])\n    }\n\n    @Test(\"the seed store's shards read as they were written\", .enabled(if: FileManager.default.fileExists(atPath: Fixture.seedStore.appendingPathComponent(\"ai_video_0711_meta.json\").path)))\n    func readsRa() throws {\n        let shard = try FeatureShard.read(\"ai_video_0711\", in: Fixture.seedStore)\n        #expect(shard.count == 112)\n        #expect(shard.columns[.dinoNorm]?.count == 112 * 384)\n        #expect(shard.columns[.cap]?.count == 112 * 9)\n        #expect(shard.rows.allSatisfy { $0.label == 1 && $0.id.count == 40 })\n        #expect(shard.metadata.isEmpty)\n    }\n}\n"},{"path":"Tests/VeilGardeCoreTests/SupportTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,101]],"header":{"lines":[1,9],"target":"VeilGardeCoreTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1848,"scopes":[["S","SupportTests",null,"",15,16,[16,20],101,null,-1,0,"a"],["S","Sample",null,"",17,17,[17,38],17,null,0,8,"a"],["f","stableJSON",[],"",19,20,[20,29],26,null,0,0,"a"],["f","hashes",[],"",28,29,[29,18],32,null,0,0,"a"],["f","safetensorsRoundTrip",[],"",34,35,[35,39],55,null,0,0,"a"],["f","stableSplit",[],"",57,58,[58,23],65,null,0,0,"a"],["f","splitMix",[],"",67,68,[68,20],76,null,0,0,"a"],["f","toml",[],"",78,79,[79,23],91,null,0,0,"a"],["f","workArea",[],"",93,94,[94,20],100,null,0,0,"a"]],"old":"","new":"//\n//  SupportTests.swift\n//  VeilGardeCoreTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The support layer's promises: stable JSON bytes, known hash vectors, safetensors that\n//        round-trip every dtype and write the same bytes twice, splits that never move, a seeded\n//        generator that replays, and the recipe TOML subset.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeCore\n\n@Suite(\"Support\")\nstruct SupportTests {\n    struct Sample: Codable, Equatable { var b: Int; var a: String; var nan: Double }\n\n    @Test(\"JSON encodes sorted keys and the same bytes every time\")\n    func stableJSON() throws {\n        let value = Sample(b: 2, a: \"x/y\", nan: .nan)\n        let one = try JSONCoding.line(value)\n        #expect(one == #\"{\"a\":\"x/y\",\"b\":2,\"nan\":\"nan\"}\"#)\n        #expect(try JSONCoding.line(value) == one)\n        #expect(JSONCoding.standardized(#\"{\"v\": NaN, \"s\": \"NaN\"}\"#) == #\"{\"v\": \"nan\", \"s\": \"NaN\"}\"#)\n    }\n\n    @Test(\"SHA-256 and SHA-1 match their published vectors\")\n    func hashes() {\n        #expect(ContentHash.sha256Hex(\"abc\") == \"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad\")\n        #expect(ContentHash.sha1Hex(Data(\"abc\".utf8)) == \"a9993e364706816aba3e25717850c26c9cd0d89d\")\n    }\n\n    @Test(\"safetensors round-trip every dtype and write identical bytes\")\n    func safetensorsRoundTrip() throws {\n        let entries = [\n            SafetensorsWriter.Entry(\"z_f32\", shape: [2, 3], .float32([0, 1.5, -2, .infinity, 3e-38, 7])),\n            SafetensorsWriter.Entry(\"a_i32\", shape: [3], .int32([-1, 0, Int32.max])),\n            SafetensorsWriter.Entry(\"m_i16\", shape: [2], .int16([-7, 300])),\n            SafetensorsWriter.Entry(\"u_u8\", shape: [4], .uint8([0, 1, 254, 255])),\n            SafetensorsWriter.Entry(\"h_f16\", shape: [2], .float16Bits([0x3C00, 0xC000])),\n        ]\n        let data = try SafetensorsWriter.encode(entries, metadata: [\"format\": \"test-v1\", \"b\": \"2\"])\n        #expect(try SafetensorsWriter.encode(entries.reversed(), metadata: [\"b\": \"2\", \"format\": \"test-v1\"]) == data)\n        let file = try SafetensorsFile(data: data)\n        #expect(file.metadata == [\"format\": \"test-v1\", \"b\": \"2\"])\n        #expect(try file.float32(\"z_f32\") == [0, 1.5, -2, .infinity, 3e-38, 7])\n        #expect(try file.tensor(\"z_f32\").shape == [2, 3])\n        #expect(try file.int32(\"a_i32\") == [-1, 0, Int32.max])\n        #expect(try file.int16(\"m_i16\") == [-7, 300])\n        #expect(try file.uint8(\"u_u8\") == [0, 1, 254, 255])\n        #expect(try file.float32(\"h_f16\") == [1, -2])\n        let headerLength = data.withUnsafeBytes { Int(UInt64(littleEndian: $0.loadUnaligned(as: UInt64.self))) }\n        #expect((8 + headerLength) % 8 == 0)\n    }\n\n    @Test(\"a split assignment never moves and its fractions hold\")\n    func stableSplit() {\n        #expect(StableSplit.unit(\"IMG_0291\", salt: \"split:v1\") == StableSplit.unit(\"IMG_0291\", salt: \"split:v1\"))\n        #expect(StableSplit.unit(\"IMG_0291\", salt: \"split:v1\") != StableSplit.unit(\"IMG_0291\", salt: \"platt:v1\"))\n        var counts: [Partition: Int] = [:]\n        for i in 0..<10_000 { counts[StableSplit.partition(\"stem-\\(i)\", salt: \"split:v1\", train: 0.70, val: 0.15), default: 0] += 1 }\n        #expect(abs(Double(counts[.train] ?? 0) / 10_000 - 0.70) < 0.02)\n        #expect(abs(Double(counts[.val] ?? 0) / 10_000 - 0.15) < 0.02)\n    }\n\n    @Test(\"SplitMix64 replays its sequence and shuffles every index once\")\n    func splitMix() {\n        var a = SplitMix64(seed: 42)\n        var b = SplitMix64(seed: 42)\n        #expect((0..<8).map { _ in a.next() } == (0..<8).map { _ in b.next() })\n        var c = SplitMix64(seed: 7)\n        #expect(Set(c.permutation(100)) == Set(0..<100))\n        var d = SplitMix64(seed: 1)\n        #expect((0..<1000).allSatisfy { _ in (0..<1).contains(d.unit()) })\n    }\n\n    @Test(\"the recipe TOML subset parses tables, values and comments\")\n    func toml() throws {\n        let document = try TOMLSubset.parse(\"\"\"\n        id = \"shipped\" # the recipe\n        [warp]\n        trees = 200\n        eta = 0.05\n        heads = [\"art\", \"blur\"]\n        \"\"\")\n        #expect(TOMLSubset.value(document, \"\", \"id\")?.string == \"shipped\")\n        #expect(TOMLSubset.value(document, \"warp\", \"trees\")?.integer == 200)\n        #expect(TOMLSubset.value(document, \"warp\", \"eta\")?.float == 0.05)\n        #expect(TOMLSubset.value(document, \"warp\", \"heads\")?.strings == [\"art\", \"blur\"])\n    }\n\n    @Test(\"the work area is the one the environment names, else none; the datasets theirs, else the work area's\")\n    func workArea() {\n        #expect(WorkArea.resolve(environment: [\"VEILGARDE_WORK_AREA\": \"/tmp/vg-area\"])?.root.path == \"/tmp/vg-area\")\n        #expect(WorkArea.resolve(environment: [:]) == nil && WorkArea.resolve(environment: [\"VEILGARDE_WORK_AREA\": \"\"]) == nil)\n        #expect(WorkArea.datasets(environment: [\"VEILGARDE_WORK_AREA\": \"/tmp/vg-area\"])?.path == \"/tmp/vg-area/datasets\")\n        #expect(WorkArea.datasets(environment: [\"VEILGARDE_WORK_AREA\": \"/tmp/vg-area\", \"VEILGARDE_DATASETS\": \"/data\"])?.path == \"/data\")\n        #expect(WorkArea.datasets(environment: [:]) == nil)\n    }\n}\n"}]};
